using System;using System.Collections.Generic;using System.Linq;using System.Reflection;using System.Text.Json;using Deception.Core;using Deception.PolyModAdapter;
public class Obj{static long Next;public long Pointer{get;}=++Next;public bool Alive=true;public Go gameObject{get;}=new();}
public class Go{public bool activeInHierarchy{get;set;}=true;}
public readonly record struct WorldCoordinates(int X,int Y);
public class UnitState:Obj{public uint id{get;set;}=7;public WorldCoordinates coordinates{get;set;}=new(1,1);public ushort health{get;set;}=10;public byte owner{get;set;}=1;}
public class Unit:Obj{public UnitState UnitState{get;set;}=null!;public bool Visible=true,Hidden;public bool GetVisible()=>Visible;public bool IsInvisibleForLocalPlayer()=>Hidden;}
public class TileData:Obj{public UnitState? unit{get;set;}public bool Explored=true,Public=true;public bool GetExplored(byte viewer)=>Explored;public UnitState? GetUnit(GameState state,byte viewer,bool a)=>Public?unit:null;}
public class Tile:Obj{public TileData Data{get;set;}=new();public Unit? unit{get;set;}public bool IsHidden{get;set;}}
public class MapData{public Dictionary<WorldCoordinates,TileData> Tiles=new();}
public class GameState:Obj{public uint CurrentTurn{get;set;}=5;public MapData Map{get;set;}=new();public Dictionary<uint,UnitState> Units=new();public bool TryGetUnit(uint id,out UnitState? u)=>Units.TryGetValue(id,out u);}
public class Player:Obj{public byte Id{get;set;}=1;}
public class Client:Obj{public GameState GameState{get;set;}=null!;public bool IsReplay,IsSpectating;}
public static class GameManager{public static GameState GameState{get;set;}=null!;public static Client Client{get;set;}=null!;public static Player LocalPlayer{get;set;}=null!;public static bool Viewing=true;}
public class MapRenderer:Obj{public static MapRenderer Current{get;set;}=null!;public Dictionary<WorldCoordinates,Tile> Tiles=new();public Dictionary<uint,Unit> Units=new();public Tile? GetTileInstance(WorldCoordinates at)=>Tiles.GetValueOrDefault(at);public Unit? GetUnitInstance(uint id)=>Units.GetValueOrDefault(id);}
public static class MapDataExtensions{public static TileData? GetTile(MapData m,WorldCoordinates at)=>m.Tiles.GetValueOrDefault(at);}
namespace Deception.PolyModAdapter{
 internal static class Entry{internal static List<string> Errors=new();internal static void Note(string k,string m)=>Errors.Add(k+":"+m);}
 internal static class Native{
  const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance;
  internal static Type T(string name)=>typeof(Native).Assembly.GetType(name,true)!;
  internal static object? Get(object o,string name)=>o.GetType().GetProperty(name,F)?.GetValue(o)??o.GetType().GetField(name,F)?.GetValue(o);
  internal static object? Static(string type,string name)=>T(type).GetProperty(name,F)!.GetValue(null);
  internal static MethodInfo M(string t,string name,params string[] args)=>T(t).GetMethods(F).Single(m=>m.Name==name&&m.GetParameters().Length==args.Length);
  internal static object? Invoke(MethodInfo m,object? o,params object?[] args)=>m.Invoke(o,args);
  internal static bool Same(object? a,object? b)=>a is not null&&ReferenceEquals(a,b);internal static bool UnityAlive(object? o)=>o is Obj v&&v.Alive;
  internal static int Int(object? o)=>Convert.ToInt32(o);internal static long Pointer(object o)=>((Obj)o).Pointer;
 }
 internal static class NativeGameStateEnvelope{
  internal sealed class Snapshot{internal long Revision;readonly byte[] Bytes0;internal Snapshot(NativeIdentityLedger l,long r){Revision=r;Bytes0=NativeIdentityLedgerCodec.Encode(l,r);}internal byte[] Bytes()=>Bytes0.ToArray();internal Guid Epoch=>NativeIdentityLedgerCodec.Decode(Bytes0,Revision).Epoch;}
  internal static Dictionary<object,Snapshot> Frames=new();internal static Snapshot? Get(object state)=>Frames.GetValueOrDefault(state);
 }
 internal static class NativeRegroupSession{internal static bool Ready=true;internal static LedgerUnit? ReadIdentity(object state,uint id){var s=NativeGameStateEnvelope.Get(state);return s is null||!Ready?null:NativeIdentityLedgerCodec.Decode(s.Bytes(),s.Revision).Units.SingleOrDefault(r=>r.Alive&&r.NativeId==id&&r.Independent);}}
 internal static class NativeShedDisguise{internal static Func<object,object,Action?>? PreparePresentation;}
 internal static class NativeDisguiseMovement{internal static Func<object,object,Action?>? PreparePresentation;}
 internal static class NativeDisguiseLifecycle{internal static Func<object,object,Action?>? PreparePresentation;}
 internal static class NativeExchangeTransformationVisual{
  internal static bool Curtain;
  internal static bool Context(object s,object m,object c,object p,byte v)=>NativeRegroupSession.Ready&&Native.Same(s,GameManager.GameState)&&Native.Same(m,MapRenderer.Current)&&Native.Same(c,GameManager.Client)&&Native.Same(p,GameManager.LocalPlayer)&&Native.Same(((Client)c).GameState,s)&&((Player)p).Id==v&&Native.UnityAlive(m)&&!((Client)c).IsReplay&&!((Client)c).IsSpectating&&!Curtain&&GameManager.Viewing;
  internal static bool CanShowEndpoint(object s,object m,byte viewer,object at){var t=((MapRenderer)m).GetTileInstance((WorldCoordinates)at);return t is not null&&t.Alive&&t.gameObject.activeInHierarchy&&!t.IsHidden&&t.Data.Explored&&t.Data.Public&&t.unit is {Visible:true,Hidden:false};}
  internal static bool Authorized(object state,NativeExchangeIntent intent){var f=NativeGameStateEnvelope.Get(state);return f is not null&&NativeExchangeIntentCodec.AlreadyCommitted(NativeIdentityLedgerCodec.Decode(f.Bytes(),f.Revision),f.Revision,intent);}
 }
 internal static class MimicRegroupAnimation{
  internal static Func<object,NativeExchangeIntent,bool>? ShedReaction;internal static Action? ShedTick,ShedClear;
  internal static List<(object State,int X,int Y,Func<bool> Guard)> Calls=new();internal static bool Throw;
  internal static bool StartShedCue(object s,int x,int y,Func<bool> valid){if(Throw)throw new Exception("cue");Calls.Add((s,x,y,valid));return true;}
 }
}
public static class ShedPresentationTests{
 static int Assertions;static readonly List<string> Tests=new();static double Time;
 static void Check(bool b,string s){Assertions++;if(!b)throw new Exception(s);}static void Test(string name,Action f){Reset();try{f();Tests.Add(name);}catch(Exception e){throw new Exception(name,e);}}
 static GameState S=null!;static UnitState Body=null!;static Unit Rendered=null!;static Tile Source=null!,Destination=null!;static NativeIdentityLedger Ledger=null!;static NativeExchangeIntent Intent=null!;
 static void Reset(){NativeShedPresentation.Clear();NativeShedPresentation.Install();Time=0;NativeShedPresentation.Clock=()=>Time;NativeGameStateEnvelope.Frames.Clear();MimicRegroupAnimation.Calls.Clear();MimicRegroupAnimation.Throw=false;NativeRegroupSession.Ready=true;NativeExchangeTransformationVisual.Curtain=false;GameManager.Viewing=true;Entry.Errors.Clear();
  S=new();Body=new();Rendered=new(){UnitState=Body};Source=new(){unit=Rendered};Source.Data.unit=Body;Destination=new();S.Map.Tiles[new(1,1)]=Source.Data;S.Map.Tiles[new(2,1)]=Destination.Data;S.Units[7]=Body;GameManager.GameState=S;GameManager.Client=new(){GameState=S};GameManager.LocalPlayer=new();MapRenderer.Current=new();MapRenderer.Current.Tiles[new(1,1)]=Source;MapRenderer.Current.Tiles[new(2,1)]=Destination;MapRenderer.Current.Units[7]=Rendered;
  var a=new LedgerAppearance("warrior",new("Imperius","Default"),new("Imperius","Default"),new("Imperius","Default"),0,100,100,false,ApparentConcealment.Visible,-1,Array.Empty<string>());
  var row=new LedgerUnit(8,7,true,LedgerActualKind.Mimic,true,a,PaidInvestmentKind.Known,3);Ledger=new(Guid.Parse("2474a827-90bb-49d1-a81a-ad2de330497d"),9,1,new[]{row},Array.Empty<LedgerReceipt>());Publish(0);
  var u=new NativeExchangeUnit(8,7,1,1);Intent=new(Ledger.Epoch,1,0,5,1,NativeExchangeKind.ShedDisguise,false,NativePartnerReference.Existing,9,u,u,NativeExchangeIntentCodec.AppearanceFingerprint(a));
 }
 static void Publish(long revision)=>NativeGameStateEnvelope.Frames[S]=new(Ledger,revision);
 static void Commit(bool move=false,bool rebind=false,bool genuine=false){var row=Ledger.Units[0];if(move){Source.Data.unit=null;Source.unit=null;Body.coordinates=new(2,1);Destination.Data.unit=Body;}if(rebind){var old=Body;Body=new(){id=9,coordinates=old.coordinates};S.Units.Remove(old.id);S.Units[9]=Body;(move?Destination:Source).Data.unit=Body;row=row with{NativeId=9};}
  row=genuine?row with{Kind=LedgerActualKind.Genuine,Independent=false,Appearance=null}:row with{Appearance=row.Appearance! with{Form=RecruitmentCatalog.MenuId,Health=10,Maximum=10}};
  Ledger=Ledger with{NextLogicalId=rebind?11ul:9ul,NextSequence=genuine?1ul:2ul,Units=new[]{row},Receipts=genuine?Array.Empty<LedgerReceipt>():new[]{new LedgerReceipt(1,NativeExchangeIntentCodec.Operation(1),NativeExchangeIntentCodec.Fingerprint(Intent),0,1,new[]{8ul})}};Publish(genuine?0:1);
 }
 static void RenderArrival(){Rendered.UnitState=Body;MapRenderer.Current.Units.Clear();MapRenderer.Current.Units[Body.id]=Rendered;var t=MapRenderer.Current.GetTileInstance(Body.coordinates)!;t.unit=Rendered;}
 public static int Run(){try{
  Test("manual completion and native reaction share exactly one cue",()=>{var done=NativeShedDisguise.PreparePresentation!(S,Body);Check(done is not null,"no capture");Commit();done!();done();Check(NativeShedPresentation.ActiveCount==1,"duplicate completion queued twice");Check(NativeShedPresentation.Reaction(S,Intent),"Shed not intercepted");NativeShedPresentation.Tick();NativeShedPresentation.Reaction(S,Intent);NativeShedPresentation.Tick();Check(MimicRegroupAnimation.Calls.Count==1&&MimicRegroupAnimation.Calls[0].Guard(),"manual reaction duplicated or failed cue");});
  foreach(bool genuine in new[]{false,true})Test("automatic move waits for exact destination renderer "+genuine,()=>{if(genuine){Ledger=Ledger with{Units=new[]{Ledger.Units[0] with{Kind=LedgerActualKind.Genuine}}};Publish(0);}var done=NativeDisguiseMovement.PreparePresentation!(S,Body);Check(done is not null,"move not captured");Commit(move:true,genuine:genuine);done!();NativeShedPresentation.Tick();Check(MimicRegroupAnimation.Calls.Count==0&&NativeShedPresentation.ActiveCount==1,"cue fired before visual arrival");RenderArrival();Time=.4;NativeShedPresentation.Tick();Check(MimicRegroupAnimation.Calls.Count==1&&MimicRegroupAnimation.Calls[0].X==2,"auto shed destination cue absent");});
  Test("native coast rebind follows final exposed identity",()=>{var done=NativeShedPresentation.Prepare(S,Body);Commit(move:true,rebind:true);done!();NativeShedPresentation.Tick();Check(MimicRegroupAnimation.Calls.Count==0,"old wrapper borrowed cue");RenderArrival();NativeShedPresentation.Tick();Check(MimicRegroupAnimation.Calls.Count==1&&Ledger.Units[0].NativeId==9,"new root did not receive cue");});
  Test("genuine native reveal at same revision shares move cue",()=>{Ledger=Ledger with{Units=new[]{Ledger.Units[0] with{Kind=LedgerActualKind.Genuine}}};Publish(0);var move=NativeDisguiseMovement.PreparePresentation!(S,Body);var reveal=NativeDisguiseLifecycle.PreparePresentation!(S,Body);Check(move is not null&&reveal is not null,"native reveal not captured");Commit(genuine:true);reveal!();move!();NativeShedPresentation.Tick();Check(MimicRegroupAnimation.Calls.Count==1&&NativeGameStateEnvelope.Get(S)!.Revision==0,"same-revision native reveal missed or duplicated");});
  Test("observed pre-move event survives temporarily unavailable reveal renderer",()=>{var move=NativeDisguiseMovement.PreparePresentation!(S,Body);Rendered.Visible=false;var reveal=NativeDisguiseLifecycle.PreparePresentation!(S,Body);Commit();reveal!();Rendered.Visible=true;move!();NativeShedPresentation.Tick();Check(MimicRegroupAnimation.Calls.Count==1,"late unavailable renderer vetoed original observed event");});
  Test("canceled hidden attempt does not suppress next accepted event",()=>{Source.IsHidden=true;var canceled=NativeShedPresentation.Prepare(S,Body);Source.IsHidden=false;var accepted=NativeShedPresentation.Prepare(S,Body);Commit();accepted!();NativeShedPresentation.Tick();Check(canceled is not null&&MimicRegroupAnimation.Calls.Count==1,"uncommitted hidden capture blocked new accepted event");});
  Test("dead unit does not reserve a shed cue",()=>{Body.health=0;Check(NativeShedPresentation.Prepare(S,Body) is null,"death incorrectly reserved living transform cue");});
  foreach(string f in new[]{"cancel","unchanged-mask","rollback"})Test("unsuccessful shedding remains silent "+f,()=>{var done=NativeShedPresentation.Prepare(S,Body);if(f=="unchanged-mask")Publish(1);if(f=="rollback"){Commit();Reset();}done!();NativeShedPresentation.Tick();Check(MimicRegroupAnimation.Calls.Count==0&&NativeShedPresentation.ActiveCount==0,"noncommit emitted cue");});
  foreach(string f in new[]{"fog","unexplored","hidden-unit","invisible","unready","replay","spectator","curtain","different-client-state"})Test("unobserved source cannot reserve cue "+f,()=>{switch(f){case "fog":Source.IsHidden=true;break;case "unexplored":Source.Data.Explored=false;break;case "hidden-unit":Rendered.Visible=false;break;case "invisible":Rendered.Hidden=true;break;case "unready":NativeRegroupSession.Ready=false;break;case "replay":GameManager.Client.IsReplay=true;break;case "spectator":GameManager.Client.IsSpectating=true;break;case "curtain":NativeExchangeTransformationVisual.Curtain=true;break;default:GameManager.Client.GameState=new();break;}var capture=NativeShedPresentation.Prepare(S,Body);if(f is "fog" or "unexplored" or "hidden-unit" or "invisible"){Check(capture is not null,"completion suppression not reserved");Commit();capture!();Source.IsHidden=false;Source.Data.Explored=true;Rendered.Visible=true;Rendered.Hidden=false;NativeShedPresentation.Reaction(S,Intent);NativeShedPresentation.Tick();Check(MimicRegroupAnimation.Calls.Count==0,"later-visible reaction invented hidden shed event");}else Check(capture is null,"unauthorized context captured");});
  foreach(string f in new[]{"turn","viewer","client","map","epoch","clear","fog","dead","no-longer-exposed","pool-rebind","timeout"})Test("delayed stale cue is discarded "+f,()=>{var done=NativeShedPresentation.Prepare(S,Body);Commit(move:true);done!();switch(f){case "turn":S.CurrentTurn++;break;case "viewer":GameManager.LocalPlayer=new(){Id=2};break;case "client":GameManager.Client=new(){GameState=S};break;case "map":MapRenderer.Current=new();break;case "epoch":Ledger=Ledger with{Epoch=Guid.NewGuid()};Publish(1);break;case "clear":NativeShedPresentation.Clear();break;case "fog":Destination.IsHidden=true;break;case "dead":Body.health=0;break;case "no-longer-exposed":Ledger=Ledger with{Units=new[]{Ledger.Units[0] with{Appearance=Ledger.Units[0].Appearance! with{Form="warrior",Health=100,Maximum=100}}}};Publish(2);break;case "pool-rebind":Destination.Data=new();break;case "timeout":Time=1.6;break;}if(MapRenderer.Current.GetTileInstance(Body.coordinates) is not null)RenderArrival();NativeShedPresentation.Tick();Check(MimicRegroupAnimation.Calls.Count==0,"stale cue emitted");Time=3;NativeShedPresentation.Tick();Check(NativeShedPresentation.ActiveCount==0,"stale cue retained");});
  Test("native reaction can admit observed enrolled opponent recap",()=>{Commit();Check(NativeShedPresentation.Reaction(S,Intent),"reaction not handled");NativeShedPresentation.Tick();Check(MimicRegroupAnimation.Calls.Count==1,"visible native reaction cue absent");});
  Test("superseded same-body cue and historical reaction cannot replay",()=>{var done=NativeShedPresentation.Prepare(S,Body);Commit(move:true);done!();Publish(3);RenderArrival();NativeShedPresentation.Tick();Check(MimicRegroupAnimation.Calls.Count==0&&NativeShedPresentation.ActiveCount==0,"old shed survived newer authoritative event");NativeShedPresentation.Reaction(S,Intent);NativeShedPresentation.Tick();Check(MimicRegroupAnimation.Calls.Count==0,"old committed receipt resurrected superseded cue");});
  Test("completed cue authorization expires with newer authoritative frame",()=>{var done=NativeShedPresentation.Prepare(S,Body);Commit();done!();NativeShedPresentation.Tick();Check(MimicRegroupAnimation.Calls.Single().Guard(),"cue never authorized");Publish(2);Check(!MimicRegroupAnimation.Calls.Single().Guard(),"old animation retained authority");});
  Test("invalid receipt and old turn reaction are silent",()=>{NativeShedPresentation.Reaction(S,Intent);NativeShedPresentation.Tick();Check(MimicRegroupAnimation.Calls.Count==0,"uncommitted reaction emitted");Commit();S.CurrentTurn++;NativeShedPresentation.Reaction(S,Intent);NativeShedPresentation.Tick();Check(MimicRegroupAnimation.Calls.Count==0,"old turn replay emitted");});
  Test("cue failure consumes pending event without retry or backend edits",()=>{var done=NativeShedPresentation.Prepare(S,Body);Commit();var bytes=NativeGameStateEnvelope.Get(S)!.Bytes();done!();MimicRegroupAnimation.Throw=true;NativeShedPresentation.Tick();MimicRegroupAnimation.Throw=false;NativeShedPresentation.Reaction(S,Intent);NativeShedPresentation.Tick();Check(NativeShedPresentation.ActiveCount==0&&MimicRegroupAnimation.Calls.Count==0,"failed cue retried");Check(NativeGameStateEnvelope.Get(S)!.Bytes().SequenceEqual(bytes)&&Body.health==10,"presentation changed backend state");});
  Console.WriteLine(JsonSerializer.Serialize(new{passed=true,cases=Tests.Count,assertions=Assertions,tests=Tests,nativeGame="NOT RUN"}));return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
